var html = String(result);
var re = /document\.writeln\(\qsbs\.bb\('([^']+)'\)\)/g;
var m, parts = [];
while ((m = re.exec(html)) !== null) {
  try { parts.push(String(java.base64Decode(m[1]))); } catch (e) { }
}
var body = parts.length > 0 ? parts.join('') : html;
body.replace(/<br\s*\/?\s*>/ig, '\n').replace(/<\/p>/ig, '\n')
  .replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ')
  .replace(/本章未完，点击下一页继续阅读/g, '')
  .replace(/\n{3,}/g, '\n\n').trim()
